mapper.update:
update 	project_expected_result
set		project_result_status = #{projectResultStatus},
		project_result_utime = systimestamp
where 	project_result_no = #{projectResultNo}
		and project_no = #{projectNo}

mapper.select:
select * from project_expected_result
where project_no = #{projectNo}
order by project_result_order asc
